      (136, 'MAGHAMIL, MERLYN', 'guest', 24.6, 'ngap_import', 1, 'PM', 2, 'PM', ''),
      (137, 'YU, PATRICK WILSON', 'member', 16.8, 'ngap_import', 3, 'AM', 4, 'AM', ''),
      (137, 'YU, DAVE WILSON', 'guest', 12.3, 'ngap_import', 3, 'AM', 4, 'AM', ''),
      (138, 'ZARAGOZA, AMOR', 'member', 14.8, 'ngap_import', 3, 'PM', 4, 'PM', ''),
      (138, 'RODRIGUEZ, JOSHUA', 'guest', 14.4, 'ngap_import', 3, 'PM', 4, 'PM', ''),
      (139, 'PALIC, CHRYSLER ANNE', 'member', 21.8, 'ngap_import', null, null, null, null, 'No schedule on the club sheet.'),
      (139, 'DACLES, JANIREE', 'guest', 19.1, 'ngap_import', null, null, null, null, 'No schedule on the club sheet.'),
      (140, 'VILLARUZ, CHIKKI', 'member', 24.4, 'ngap_import', 3, 'PM', 4, 'PM', ''),
      (140, 'RUBICO, RIC', 'guest', 23.8, 'ngap_import', 3, 'PM', 4, 'PM', ''),
      (141, 'NUFABLE, STEPHEN', 'member', 30.0, 'ngap_import', 2, 'PM', 3, 'PM', ''),
      (141, 'YAO, JOHNNIE', 'guest', 0.0, 'manual', 2, 'PM', 3, 'PM', 'No index on the club sheet; 0 was recorded.'),
      (142, 'PALACIOS, BRENT', 'member', 19.9, 'ngap_import', 2, 'AM', 3, 'AM', ''),
      (142, 'LEVESTE,', 'guest', 0.0, 'manual', null, null, null, null, 'The name on the club sheet is incomplete. No index on the club sheet; 0 was recorded. No schedule on the club sheet.'),
      (143, 'AURELIO, DOUGLAS SR', 'member', 19.1, 'ngap_import', 1, 'AM', 2, 'AM', ''),
      (143, 'GORMLEY, ROBERT ANTHONY', 'guest', 16.7, 'ngap_import', 1, 'AM', 2, 'AM', ''),
      (144, 'CAMBAY, JESUS', 'member', 0.0, 'manual', 1, 'PM', 2, 'PM', 'No index on the club sheet; 0 was recorded.'),
      (144, 'CAMBAY, JESSE CHARLO', 'guest', 0.0, 'manual', 1, 'PM', 2, 'PM', 'No index on the club sheet; 0 was recorded.')
    ) as f(pair_no, full_name, role, idx, idx_source, d1, s1, d2, s2, note)
  loop
    v_note := btrim(r.note);
    v_day_count := (case when r.d1 is null then 0 else 1 end) + (case when r.d2 is null then 0 else 1 end);
    v_write_days := v_day_count > 0;

    if v_write_days and v_required_days is not null and v_day_count <> v_required_days then
      v_note := concat_ws(' ', nullif(v_note, ''),
        format('The club sheet gives %s playing day(s); this event requires %s, so the days were left for the desk.',
               v_day_count, v_required_days));
      v_write_days := false;
    end if;

    select p.id into v_player
      from public.players p
     where p.club_id = v_club
       and lower(btrim(p.full_name)) = lower(r.full_name)
     limit 1;

    if v_player is null then
      insert into public.players (club_id, full_name)
      values (v_club, r.full_name)
      returning id into v_player;
    end if;

    if not exists (
      select 1 from public.player_memberships m
       where m.club_id = v_club and m.player_id = v_player and m.status = 'active'
    ) then
      insert into public.player_memberships (club_id, player_id, membership_type)
      values (v_club, v_player, r.role);
    end if;

    -- Every player has a record on file, including the 0 recorded where the sheet had no index, so
    -- the player card and the draw never disagree about the number they play off.
    insert into public.handicap_records (club_id, player_id, handicap_index, effective_date, source)
    values (v_club, v_player, r.idx, v_cutoff, r.idx_source)
    on conflict (player_id, effective_date)
    do update set handicap_index = excluded.handicap_index, source = excluded.source;

    v_reasons := case when v_note = '' then '{}'::text[] else array[v_note] end;

    -- Every player on the sheet is ready to play. The note is kept as a reason the desk can read;
    -- it no longer holds anyone out of the draw.
    -- The pair number rides along in the registration answers so the draw keeps a member and their
    -- guest in one group, whatever group size the event uses.
    insert into public.registrations as reg
      (club_id, tournament_id, player_id, frozen_index, status, reasons, answers)
    values (v_club, v_tournament, v_player, r.idx, 'ok', v_reasons,
            jsonb_build_object('teamNo', r.pair_no))
    on conflict (tournament_id, player_id)
    do update set frozen_index = excluded.frozen_index,
                  status = excluded.status,
                  reasons = excluded.reasons,
                  answers = coalesce(reg.answers, '{}'::jsonb)
                            || jsonb_build_object('teamNo', r.pair_no)
    returning id into v_reg;

    if v_write_days then
      insert into public.registration_days (club_id, registration_id, tournament_day_id, selected, session)
      select v_club, v_reg, d.id, true, s.session
        from (values (r.d1, r.s1), (r.d2, r.s2)) as s(day_no, session)
        join public.tournament_days d
          on d.tournament_id = v_tournament
         and d.club_id = v_club
         and d.day_number = s.day_no
         and d.is_playing_day
       where s.day_no is not null
      on conflict (registration_id, tournament_day_id)
      do update set selected = true, session = excluded.session, updated_at = now();
    end if;

    -- A day the club no longer gives this player is released, keeping the row for the desk.
    update public.registration_days rd
       set selected = false,
           session = null,
           tee_time = null,
           start_hole = null,
           tee_confirmed = false,
           updated_at = now()
     where rd.registration_id = v_reg
       and rd.selected
       and not exists (
         select 1 from public.tournament_days d
          where d.id = rd.tournament_day_id
            and d.day_number in (coalesce(r.d1, -1), coalesce(r.d2, -1))
       );
  end loop;

  -- Players on the sheet with no guest partner yet. Directory entries only: no index, no
  -- registration, nothing guessed about the days they will play.
  for w in
    select * from (values
      (1, 'ALAS-AS, FRED'),
      (2, 'BARCARLOS, GRETCHEN'),
      (4, 'DIAZ, JAN JASON'),
      (5, 'DIVINAGRACIA, ANN'),
      (7, 'LIM, ADOY'),
      (8, 'MIN, HYANG GEE'),
      (13, 'PALACIOS, CHRISLINE'),
      (14, 'PAMONAG, RAYMART'),
      (15, 'SEO, EUN JIN'),
      (16, 'SUPERFICIAL, DENNIS'),
      (17, 'TAMBA, DAL'),
      (18, 'VILLANUEVA, GIL'),
      (20, 'YOUN, SMITH'),
      (21, 'GORRICETA, MICHAEL'),
      (22, 'ALQUIROS, IRA'),
      (23, 'VILLASIS, DIOSCORO'),
      (24, 'DAANOY, NORMAN')
    ) as f(pair_no, full_name)
  loop
    if not exists (
      select 1 from public.players p
       where p.club_id = v_club and lower(btrim(p.full_name)) = lower(w.full_name)
    ) then
      insert into public.players (club_id, full_name)
      values (v_club, w.full_name);
    end if;
  end loop;
end $$;

